  if (/^(iabjs|chrome-extension|moz-extension|safari-web-extension|safari-extension):/.test(f)) return false;
  if (/\/(game|wave-map)\.js(\?|$)/.test(f)) return true;                    // our own files by name, whatever origin serves them (file://, localhost, the CNAME to come)
