            d.textContent = 'THE CRASH LOG (' + o.rows.length + ' entries, newest first — send to the dev):\n\n' + o.rows.map(function (r) { return r.t + ' · ' + r.ver + '\n' + r.trace; }).join('\n\n————\n\n');
