// THE KINGPIN — one boss, guarding the megatower. He does not respawn.
function pickBossPerches() {
  if (gameMode === 'wave') {
    // wave mode: he takes the NEAREST rooftop to wherever the fight is
    boss.perches = platforms.filter(p => p.kind === 'bsurf' && p.dy >= 350 && p.w >= 100 && p.x > STREET_MIN)
                            .map(p => ({ x: p.x + p.w / 2, dy: p.dy, x0: p.x + 10, x1: p.x + p.w - 10 }))
                            .sort((a, b) => Math.abs(a.x - boss.x) - Math.abs(b.x - boss.x));
  } else {
    // story: his crown perches — the megatower's highest platforms
    boss.perches = platforms.filter(p => p.kind === 'bsurf' && p.dy > 1500 * BZ && p.x > (BLDG_AT[4] != null ? BLDG_AT[4] : -1e9) - 112 * BZ && p.w >= 100)
                            .map(p => ({ x: p.x + p.w / 2, dy: p.dy, x0: p.x + 10, x1: p.x + p.w - 10 }))
                            .sort((a, b) => b.dy - a.dy);
  }
  if (!boss.perches.length) boss.perches = [{ x: 5458, dy: 1774, x0: 5398, x1: 5518 }];
}
