const PVLOG = { v: new Float32Array(160), i: 0, n: 0 };   // 2.67s deep — past `LEADLAG`'s 2.5s roof,
// because a dial whose roof the buffer cannot serve is a dial that lies quietly at its own extreme.
function pvPush(vx) {
  PVLOG.v[PVLOG.i] = vx; PVLOG.i = (PVLOG.i + 1) % PVLOG.v.length;
  if (PVLOG.n < PVLOG.v.length) PVLOG.n++;
}
// `lagSec` seconds back, saturating at however much history exists. Early in a life the ring is short,
// so it returns the OLDEST sample it has rather than a zero — a zero would read as "he was standing
// still", which is a lie that would silently delete the lead for the first half-second of every run.
function pvCarried(lagSec) {
  if (PVLOG.n === 0) return 0;
  const back = Math.min(PVLOG.n, Math.max(1, Math.round(lagSec * 60)));
  return PVLOG.v[(PVLOG.i - back + PVLOG.v.length) % PVLOG.v.length];
}

