  for (let k54 = REFL_BODIES.length - 1; k54 >= 0; k54--) {
    const b54 = REFL_BODIES[k54];
    b54.on = false; b54.dead = false; b54.ceremonyT = 0; b54.tele = null; b54.orb = null; b54.storm = [];
    b54.__rd = null;   // p155: the wingman dies with its owner's run
    b54.deathT = 0; if (b54.shards) b54.shards.length = 0;
    if (k54 > 0) REFL_BODIES.splice(k54, 1);
  }
  MIRROR = REFL_BODIES[0];
  for (let d54 = pulses.length - 1; d54 >= 0; d54--) if (pulses[d54].owner === 'mirror') pulses.splice(d54, 1);
