  const say2SC = (L) => (sec72.miss ? L + (sec72.shape ? '   \"' + sec72.miss + '\" is a wave SHAPE — it can be the BOSS, never the 2nd'
                                                       : '   NO SUCH 2ND BOSS: \"' + sec72.miss + '\" — this wave runs without it') : L);
