  { ta.style.position = 'fixed'; ta.style.left = '4%'; ta.style.top = '8%'; ta.style.width = '92%'; ta.style.height = '80%'; ta.style.zIndex = '99999'; ta.style.font = "12px 'Courier New', monospace"; ta.style.background = '#0b0e18'; ta.style.color = '#e8e8f0'; ta.style.border = '2px solid #ffd166'; ta.style.padding = '10px'; }
  if (document.body && document.body.appendChild) document.body.appendChild(ta);
