  try { copied = !!(document.execCommand && document.execCommand('copy')); } catch (e) { copied = false; }
  if (copied && ta.parentNode && ta.parentNode.removeChild) { ta.parentNode.removeChild(ta); return true; }
  // it stays on screen, selected, with a way out. THIS is the rung that cannot fail.
