  ctx.fillStyle = '#ffce54';
  fitPut('death', 'graph-legend-style', 'STYLE PER WAVE  ·  PEAK ' + sMax, gx + gw, capY, gw * 0.46, TYPE.chip, '700', 'right');
  ctx.fillStyle = 'rgba(255,255,255,0.55)';
