  const btnY = (boxRoom9(btnBets) >= 56 || boxRoom9(btnPlain) < 56) ? btnBets : btnPlain;   // the bets ledger keeps its seat wherever the box keeps its 56; where only one of the two fits (a ~600-tall window), the box - his order - wins and the ledger yields, booked
