      ctx.fillStyle = locked ? 'rgba(255,200,150,0.4)' : '#ffcf9a'; ctx.font = ("700 " + Math.round(13 * sc) + "px 'Courier New', monospace");
      if (vis8(ry8, Math.round(40 * sc))) fitPut('shop', 'refresh-btn', 'REFRESH — ' + (WSHOP.refreshCost > 0 ? '◆' + WSHOP.refreshCost : 'FREE'), rx8 + rw8 / 2, ry8 + Math.round(25 * sc), rw8 - 16, Math.round(13 * sc), '700', 'center');
      if (!locked && vis8(ry8, Math.round(40 * sc))) WMODE.btns.push({ id: 'refresh', x: rx8, y: ry8, w: rw8, h: Math.round(40 * sc) });
