  if (id === 'story-resume') {   // THE DEMO SLAB (2026-09-21): the saved leg, with the kit
    if (RELEASE.storyLocked) { SFX.dryClick(); return; } const s9 = story1SavedLeg(); if (!s9) { SFX.dryClick(); return; }
    STORY1.resumeOnce = true; STORY_STAGE.beatStart = s9; chooseMode('story'); return; }
  if (id === 'story-restart') {   // THE DEMO SLAB: forget the leg, the kit and the wraps; open from the drop
    if (RELEASE.storyLocked) { SFX.dryClick(); return; }
    try { if (typeof localStorage !== 'undefined') { localStorage.removeItem('arena_story_leg'); localStorage.removeItem('arena_story_kit'); } } catch (e) { /* session only */ }
    STORY1.resume = null; STORY1.resumeOnce = false; STORY1.saved = null; STORY_STAGE.beatStart = null; WRAPN9 = 0; chooseMode('story'); return; }
