  if (m === 'wave') { openVariantGate(); return; }   // WAVE-ORDER #1: the front-menu button opens the new mode's VARIANT GATE
  if (m === 'setter') { startSetter(); return; }   // THE FOURTH DOOR (SETTER #1): the back room opens
  lazyLoad('story');   // (v1.6.1485) THE STORY RAIL: the interiors stream in behind the briefing card (idempotent; the sims load it at the file's end)
