    ctx.beginPath(); ctx.arc(cx + ox, cy + oy - s2 * 0.20, s2 * 0.10, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath();
    ctx.moveTo(cx + ox - s2 * 0.13, cy + oy + s2 * 0.30); ctx.lineTo(cx + ox - s2 * 0.07, cy + oy - s2 * 0.04);
    ctx.lineTo(cx + ox + s2 * 0.07, cy + oy - s2 * 0.04); ctx.lineTo(cx + ox + s2 * 0.13, cy + oy + s2 * 0.30);
    ctx.closePath(); ctx.fill();
