    ctx.beginPath();
    ctx.moveTo(cx + ox - s2 * 0.32, cy + oy);
    ctx.quadraticCurveTo(cx + ox, cy + oy - s2 * 0.28, cx + ox + s2 * 0.32, cy + oy);
    ctx.quadraticCurveTo(cx + ox, cy + oy + s2 * 0.28, cx + ox - s2 * 0.32, cy + oy);
