    ctx.beginPath(); ctx.moveTo(cx, cy - S * 0.06); ctx.lineTo(cx, cy + S * 0.36); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(cx - S * 0.11, cy + S * 0.04); ctx.lineTo(cx, cy - S * 0.08); ctx.lineTo(cx + S * 0.11, cy + S * 0.04); ctx.stroke();
