    ctx.beginPath(); ctx.arc(cx, cy + S * 0.17, S * 0.30, 0, Math.PI * 2); ctx.stroke();
    ctx.beginPath(); ctx.arc(cx, cy + S * 0.17, S * 0.18, 0, Math.PI * 2); ctx.stroke();
