    for (let i7 = 0; i7 < 3; i7++) { const ox7 = cx - S * 0.22 + i7 * S * 0.16; ctx.beginPath(); ctx.moveTo(ox7, cy + S * 0.06); ctx.lineTo(ox7 + S * 0.10, cy + S * 0.18); ctx.lineTo(ox7, cy + S * 0.30); ctx.stroke(); }
    vChev(); ctx.restore(); return;
