  ctx.fillRect(x, y, w, CA.RIB + 2);
  ctx.restore();
  ctx.fillStyle = 'rgba(10,12,22,0.92)';
  fitPut(surf, id + '-ribbon', K.label, x + w / 2, y + CA.RIB - Math.round(5 * sc), w - Math.round(44 * sc), Math.round(11 * sc), '700', 'center', live ? K.col : K.dim);
  // the glyph, then the name beside it
  const by = y + CA.RIB + CA.PAD;
