  const nx = x + CA.PAD + CA.GLY + Math.round(8 * sc);
  const nw = w - (CA.PAD + CA.GLY + Math.round(8 * sc)) - CA.PAD;
  ctx.fillStyle = S.locked ? 'rgba(255,233,163,0.4)' : S.broke ? 'rgba(255,233,163,0.45)' : '#ffe9a3';
  ctx.textAlign = 'left';
  fitPut(surf, id + '-name', card.name, nx, by + Math.round(14 * sc), nw, Math.round(13 * sc), '700', 'left');
  // the caption, wrapped under the glyph row
  ctx.fillStyle = S.locked ? 'rgba(255,255,255,0.3)' : S.broke ? 'rgba(255,255,255,0.34)' : 'rgba(255,255,255,0.64)';
  let ly = by + CA.GLY + cap.px;   // below the glyph row — the same origin cardHeight reserves
  for (let i = 0; i < cap.lines.length; i++) {
    fitPut(surf, id + '-cap' + i, cap.lines[i], x + CA.PAD, ly, capW, cap.px, '', 'left');
    ly += cap.px + 3;
  }
  // the price chip, bottom-right
  const pr = '◆' + (S.price === undefined ? 0 : S.price);
  const pw = Math.max(Math.round(46 * sc), textPx(pr, Math.round(15 * sc), '700') + Math.round(14 * sc));
  const px2 = x + w - CA.PAD - pw, py2 = y + h - CA.PAD - CA.PRICE;
  roundRect(ctx, px2, py2, pw, CA.PRICE, 6);
