  roundRect(ctx, x, y, w, h, 10);
  ctx.fillStyle = 'rgba(18,28,44,0.92)'; ctx.fill();
  roundRect(ctx, x, y, w, h, 10);
  ctx.lineWidth = 2; ctx.strokeStyle = col; ctx.stroke();
