  // the glyph draws the trickle's SHAPE — the variant's feel, before a word is read
  const by = y + CARD_A.RIB + CARD_A.PAD;
  trickleGlyph((v.trick && v.trick[v.trick.length - 1] || [])[2], x + CARD_A.PAD, by, CARD_A.GLY, col);
  const nx = x + CARD_A.PAD + CARD_A.GLY + 8, nw = w - (CARD_A.PAD + CARD_A.GLY + 8) - CARD_A.PAD;
  ctx.fillStyle = '#ffe9a3';
  fitPut(surf, id + '-name', v.k + ' — ' + v.name, nx, by + 14, nw, 13, '700', 'left');
  ctx.fillStyle = 'rgba(255,255,255,0.64)';
  let ly = by + CARD_A.GLY + cap.px;   // below the glyph row — the same origin cardHeight reserves
  for (let i = 0; i < cap.lines.length; i++) { fitPut(surf, id + '-cap' + i, cap.lines[i], x + CARD_A.PAD, ly, capW, cap.px, '', 'left'); ly += cap.px + 3; }
