        ctx.fillStyle = ink; glassPut(surf, el('story', id9), label, lx + cw / 2, cy + Math.round(ch / 2) + (phone ? 9 : 5), cw - 12, px9, '700', 'center', 'rgba(10,13,20,0.92)');
