// ========================== END GAME MODES ==========================
let streetKills = 0;        // the 22 seeded rivals only — summoned waves don't count
let missionHudT = 0;

function fmtTime(t) {
  const m = Math.floor(t / 60), s = Math.floor(t % 60);
  return m + ':' + String(s).padStart(2, '0');
}

function startMission() {
  if (mission.state !== 'title' || modeSelect) return;
  if ((typeof WMODE !== 'undefined' && WMODE.screen) || (typeof TITLE9 !== 'undefined' && tutorialScreen && TITLE9.on)) return;   // (v1.6.1583) THE GATE HOLDS ITS BREATH - his red 2026-09-22 ('I skip the tutorial, and I hear shooting in the background ... then I die in the background'): the gate, the shop, the death face and the quit ask are lobbies and so is the title screen - a stray key or tap on them must not start the story mission behind the glass (on 1582 it did: 61 bodies, hearts 10 -> 0 in nine seconds, the gate still standing)
  mission.state = 'playing';
  story1Reset();   // THE FIRST LEG opens with the mission (and re-opens on RUN IT BACK)
  leftDown = rightDown = false; fireDown = pulseDown = false; spaceJustPressed = false;
  const tc = document.getElementById('titlecard');
  if (tc) tc.classList.remove('show');
  updateMissionHud();
}

function kingpinStatus() {
  if (boss.dead) return '<span class="obj-done">TOPPLED ✓</span>';
  if (boss.engaged) return boss.round === 2 ? '<b>ASCENDED</b>' : '<b>ENGAGED</b>';
  return 'AT LARGE';
}

// THE OBJECTIVE HEADER'S SEAT (THE CENSUS COLLISION, v1.6.452) — the ONE copy of this geometry. `index.html`
// carries only the STORY fallback; the wave seat and the furniture reservation both read these numbers, so a
// regression cannot hide in a stylesheet the gate cannot see. W/H are MEASURED, not typed by eye:
// `getBoundingClientRect()` in headless Chromium at 1600x900 reads the wave line at 265.14 x 21 with its right
// edge at W-18. 300 is reserved so "WAVE 12" cannot outgrow its own seat. (The STORY block is FOUR rows in the
// shipped HUD -- RIVALS / DIAMONDS / THE KINGPIN / TIME -- y14..98 by its own photograph, not the three I first
// typed from a hand-built string; corrected against gallery/second-look/census-collision/STORY-FILED/.)
const OBJ_SEAT = { WAVE_TOP: 0, STORY_TOP: 14, W: 300, H: 21, RIGHT: 18 };
function objHeaderIsWave() { return gameMode === 'wave' && !SANDBOX.on && mission.state !== 'title'; }
function updateMissionHud() {   // THE MASS-KILL FRAME (S9, 2026-09-06): the browser MARKS and flushes ONCE a frame (draw()'s HUDQ seat - updateHud's own idiom, his cut 5); killEnemy called this per counted street kill, 2,260 getElementById + style + innerHTML compares in one rocket frame. Sims keep the door synchronous: their probes call it and read #objectives in the same breath. EXACT for the world - a DOM write moved to the frame's end
  if (!globalThis.__SIM__) { HUDQ.mission = true; return; }
  missionHudFlushNow();
}
function missionHudFlushNow() {
  const el = document.getElementById('objectives');
  if (!el) return;
  // THE CENSUS COLLISION (v1.6.452): the wave-mode objective line is a SINGLE line and takes the y0..21
  // band so it stops printing through the canvas war census. Story's three-line block keeps its seat.
  // The seat is set HERE, from OBJ_SEAT, because the furniture map declares this element and a seat in the
  // stylesheet plus a rectangle in the map is one number in two places.
  if (el.style) el.style.top = (objHeaderIsWave() ? OBJ_SEAT.WAVE_TOP : OBJ_SEAT.STORY_TOP) + 'px';
  if (mission.state === 'title') { hudWrite(el, ''); return; }
  if (SANDBOX.on) { hudWrite(el, '<div class="obj-title">THE SANDBOX</div>'); return; }   // the gauge bar carries the ESC hint — once is enough; the quiet glass writes it ONCE (HITCH-HUNT #2)
  if (gameMode === 'wave') {
    hudWrite(el, '<span class="obj-label">WAVE MODE</span>&nbsp;&nbsp;WAVE ' + Math.max(1, waves.n) + ' — HOLD THE BLOCK');
    return;
  }
  const dDone = gemsTaken >= gems.length && gems.length > 0;
  const diamondRow =
    '<span class="obj-label">DIAMONDS</span>&nbsp;&nbsp;' +
      (dDone ? '<span class="obj-done">' + gems.length + '/' + gems.length + ' ✓</span>'
             : '<b>' + gemsTaken + '</b>/' + gems.length) + '<br>';
  const timeRow =
    '<span class="obj-label">TIME</span>&nbsp;&nbsp;' + fmtTime(mission.finalTime > 0 ? mission.finalTime : mission.time);
  if (mission.round === 2) {
    const r2k = Math.max(0, Math.min(streetKills - RIVAL_TOTAL, R2_TOTAL));
    const r2Done = r2k >= R2_TOTAL, bDone = !LAUNCHERS_ENABLED || blimpKills >= BLIMP_COUNT;
    el.innerHTML =
      '<span class="obj-label" style="color:#ffce54">ROUND 2</span><br>' +
      '<span class="obj-label">RIVALS</span>&nbsp;&nbsp;' +
        (r2Done ? '<span class="obj-done">' + R2_TOTAL + '/' + R2_TOTAL + ' ✓</span>'
                : '<b>' + r2k + '</b>/' + R2_TOTAL) + '<br>' +
      (LAUNCHERS_ENABLED ? ('<span class="obj-label">BLIMPS</span>&nbsp;&nbsp;' +
        (bDone ? '<span class="obj-done">' + BLIMP_COUNT + '/' + BLIMP_COUNT + ' ✓</span>'
               : '<b>' + blimpKills + '</b>/' + BLIMP_COUNT) + '<br>') : '') +
      diamondRow +
      '<span class="obj-label">THE KINGPIN</span>&nbsp;&nbsp;<span class="obj-done">DOWN ✓</span><br>' +
      timeRow;
    return;
  }
  const rDone = streetKills >= RIVAL_TOTAL;
  el.innerHTML =
    '<span class="obj-label">RIVALS</span>&nbsp;&nbsp;' +
      (rDone ? '<span class="obj-done">' + RIVAL_TOTAL + '/' + RIVAL_TOTAL + ' ✓</span>'
             : '<b>' + streetKills + '</b>/' + RIVAL_TOTAL) + '<br>' +
    diamondRow +
    '<span class="obj-label">THE KINGPIN</span>&nbsp;&nbsp;' + kingpinStatus() +
      (bossDown && !rDone ? '&nbsp;&nbsp;<span style="color:#ffce54">CLEAR THE STAGE → ROUND 2</span>' : '') + '<br>' +
    timeRow;
}

function showVictory() {
  if (mission.state === 'victory') return;
  mission.state = 'victory';
  fireDown = pulseDown = false;
  const el = document.getElementById('victorystats');
  if (el) el.innerHTML =
    'TIME&nbsp;&nbsp;<b>' + fmtTime(mission.finalTime) + '</b><br>' +
    'SCORE&nbsp;&nbsp;<b>' + score.toLocaleString() + '</b><br>' +
    'DIAMONDS&nbsp;&nbsp;<b>' + gemsTaken + '</b>&nbsp;/&nbsp;' + gems.length + '<br>' +
    'BEST COMBO&nbsp;&nbsp;<b>×' + Math.max(1, bestCombo) + '</b><br>' +
    'RIVALS CLEARED&nbsp;&nbsp;<b>' + Math.min(streetKills, RIVAL_TOTAL) + '</b>&nbsp;/&nbsp;' + RIVAL_TOTAL;
  const ov = document.getElementById('victory');
  if (ov) ov.classList.add('show');
  // triumphant little riser
  tone({ f0: 520, f1: 660, dur: 0.14, type: 'square', vol: 0.09 });
  tone({ f0: 660, f1: 880, dur: 0.14, type: 'square', vol: 0.09, delay: 0.14 });
  tone({ f0: 880, f1: 1320, dur: 0.34, type: 'square', vol: 0.1, delay: 0.28 });
  updateMissionHud();
}

