//   a weapon that no longer exists. This one is longer, opens higher, falls further and carries a receding
//   noise tail — something going away from you rather than happening at you.
function lionSkyVoice(kind, hx) {   // (2026-09-04, his red x2: 'the sound is absolutely horrible') THE
  // STRIKE'S FOUR VOICE-SETS - his ear picks at the bench (window.LIONSFX 0-3). No sawtooth anywhere:
  // the shipped fire voice opens on an 1180Hz saw, and at strike cadence that WAS the trash. Sky only;
  // the ground lion keeps its shipped throat whole.
  const s9 = (typeof window !== 'undefined' && window.LIONSFX) | 0;
  if (s9 === 3) {   // SHIPPED reference set (the A/B): the old voices, pop silent
    if (kind === 'growl') SFX.lionCharge(hx);
    if (kind === 'fire') SFX.lionFire(hx);
    return;
  }
  if (s9 === 1) {   // QUIET: barely-there air, a muted thump
    if (kind === 'pop') noise({ dur: 0.10, vol: 0.028, f0: 260, f1: 90, x: hx });
    if (kind === 'fire') { noise({ dur: 0.16, vol: 0.040, f0: 600, f1: 110, x: hx }); tone({ f0: 100, f1: 52, dur: 0.14, type: 'sine', vol: 0.03, x: hx }); }
    return;
  }
  if (s9 === 2) {   // DEEP: sub thumps, a heavier boom
    if (kind === 'pop') tone({ f0: 82, f1: 40, dur: 0.12, type: 'sine', vol: 0.055, x: hx });
    if (kind === 'growl') noise({ dur: 0.18, vol: 0.055, f0: 150, f1: 50, x: hx });
    if (kind === 'fire') { noise({ dur: 0.30, vol: 0.070, f0: 500, f1: 80, x: hx }); tone({ f0: 92, f1: 44, dur: 0.26, type: 'sine', vol: 0.055, delay: 0.02, x: hx }); }
    return;
  }
  // set 0 AIR (default): displaced air in, a low breath, a felt thump out
  if (kind === 'pop') noise({ dur: 0.16, vol: 0.050, f0: 320, f1: 80, x: hx });
  if (kind === 'growl') noise({ dur: 0.18, vol: 0.060, f0: 180, f1: 55, x: hx });
  if (kind === 'fire') { noise({ dur: 0.22, vol: 0.055, f0: 900, f1: 120, x: hx }); tone({ f0: 120, f1: 55, dur: 0.20, type: 'sine', vol: 0.045, delay: 0.02, x: hx }); }
}
