let killStreakT = -9, killStreakN = 0;   // the confirm ladder
// ---- THE DUCKING TABLE (BOOK II #262, THE MIX I) ----------------------------------------------------
// **ONE DECLARED PLACE FOR EVERY DUCK IN THE GAME.** Two duckers shipped and NEITHER IS REPLACED — this
// is the data they both read, not a third mechanism. They are not the same shape and that is the point
// of writing them down side by side:
//   THE MUSIC DUCK is a SCHEDULED RAMP on `musicGain` — down in 30ms, back over 450ms, one depth for
//   every caller. That single depth is the shipped truth and not an aspiration; `mus` below is a
//   BOOLEAN rather than a number because a per-event depth would be a promise this mechanism cannot
//   keep today, and a table that promises what the code cannot do is the caption lie one floor down.
//   THE BED DUCK is not a ramp at all — a TIMER (`BEDS.duckT`) that `bedTick` smooths toward a target,
//   ASYMMETRICALLY on purpose: beds duck fast and rise slow, so a moment lands instantly and the wind
//   comes back without a seam. Its release is honest BY CONSTRUCTION — there is no scheduled return to
//   forget, the timer simply runs out — which is why `audiosim [A4]` could always measure it.
// **THE SEVEN EVENTS ARE THE WHOLE CENSUS**, read off the call sites rather than imagined: three push both
// buses (they route through `duckMusic`, which pushes the bed itself), four push the bed alone.
// (#319) It read SIX until the blast joined, and the count is corrected IN THE SAME EDIT that added the row
//   — a table whose own header miscounts it is the #317 crime exactly, where a comment asserting the draw
//   order was inverted and a cold reader had to measure it to find out.
const DUCK = {
  MUS: { depth: 0.35, atk: 0.03, rel: 0.45 },      // -65%, and back over 450ms
  BED: { depth: 0.3, riseK: 0.8, duckK: 2.2 },     // -70%, smoothed: duck fast (2.2), rise slow (0.8)
  EV: {
    hurt:      { mus: true,  bed: 0.6 },   // the blow — and NOTHING may duck this one; see THE PAIN RULE
    mirror:    { mus: true,  bed: 0.6 },   // the encounter opens: a duck, never a lock
    freeze:    { mus: true,  bed: 0.6 },   // the world goes quiet-crackly
    stinger:   { mus: false, bed: 1.1 },   // a named wave silences the wind for its own entrance ([A11] reads this span)
    clearBell: { mus: false, bed: 0.9 },   // the bell over the vacuum
    ironheart: { mus: false, bed: 0.8 },   // the whole figure steps back, Math.max so it never fights the bell
    blast:     { mus: false, bed: 0.35 },  // (#319) the grudge detonation: the wind flinches and comes
    //   straight back. SHORT on purpose and TIER-0 ONLY at the call site — it is the most frequent
    //   event in this table by an order of magnitude, and `bedDuck` is a Math.max, so a long one held
    //   by thirty-five blasts would read as the bed simply being switched off.
  },
};
// **THE PAIN RULE (criterion C), AND IT IS A RULE ABOUT DIRECTION.** `SFX.hurt` ducks the music FOR
// ITSELF — the blow owns its moment and the beat steps back behind it. The table may never invert that
// by letting anything duck the hurt cue instead: `hurt` is a row that PUSHES, never a bus that is
// pushed, and `SFX.hurt` calls no ducker but its own. (The old `MIRVOICE` hurt-cue exemption that used
// to guard this is GONE — #130 spent the blow outside the slice where the warp is already off, so the
// hand-held dance was deleted rather than kept. `[M16]`(3) holds that and it is not re-added here.)
function duckMusic(ev) {   // sidechain by hand: music dips to the table's depth, then breathes back
  bedDuck((DUCK.EV[ev] || DUCK.EV.hurt).bed);   // (#11) what ducks the score ducks the breath
  if (!musicGain || !audioCtx) return;
  const t = audioCtx.currentTime, g = musicGain.gain;
  g.cancelScheduledValues(t);
  g.setValueAtTime(g.value, t);
  g.linearRampToValueAtTime(volMusic * DUCK.MUS.depth, t + DUCK.MUS.atk);
  g.linearRampToValueAtTime(volMusic, t + DUCK.MUS.rel);
}
function veilActive() { return VEIL.t > 0; }
function veilBegin() {
  if (dead || veilActive() || shockActive() || VEIL.meter < 0.4) return;
  if (gameTime < (VEIL.lockUntil || 0)) { tone({ f0: 220, f1: 150, dur: 0.1, type: 'square', vol: 0.06, cue: 'pilot' }); return; }   // (LION SKY 'lock' mode) the torn weather refuses to re-arm
  VEIL.t = Math.min(VEIL.meter, VEIL.dur);
  rmbVeiled = true;
  if (WRUN.on && WRUN.tAcc) { WRUN.tAcc.veilN++; WRUN.tAcc.vT0 = gameTime; }   // (tele) every escape counted
  VEIL.harvestN = 0;   // a fresh veil, a fresh harvest (#67)
  VEIL.refundM = VEIL.meter; VEIL.wasGrounded = player.grounded;   // THE INSTANT ON (RABBI-VEIL #7): a tap-cancel un-happens the newborn veil — meter and stance restored
  player.vx /= SMOKE_DIL;   // THE DASH MARRIAGE (RABBI-VEIL #10): the entry mirrors #8's exit — real velocity is continuous through the door BOTH ways, so a dash carried into the veil keeps its burst (decaying to the veiled stride on the steer)
  player.grounded = false;   // weather doesn't stand on pavement
  player.vy = 0;   // THE DRIFT DIES (RABBI-VEIL #4): no entry kick — the smoke holds its line from the first breath; it goes where you POINT it (the autopsy: the old -95/SMOKE_DIL buoyancy was a designed smoke-rises choice, not a physics leak — it could never hold the level lanes the beams rake)
  SMOKE.trail.length = 0;
  SMOKE.lastX = player.x; SMOKE.lastY = player.y;
  SMOKE.trail.push({ x: player.x, y: player.y - 44 });
  veilSmoke(player.x, player.y - 40, 10);   // you BURST into weather
  rings.push({ x: player.x, y: player.y - 44, age: 0, life: 0.14, maxR: 44, color: '#e6c8ff', wd: 3 });   // THE ACTIVATION FLASH (#73): the double-ring signature — you know, enemies know, the crowd parts
  rings.push({ x: player.x, y: player.y - 44, age: -0.04, life: 0.18, maxR: 74, color: '#9f5af0', wd: 2 });
  shake = Math.min(shake + 2, 6);   // THE SATISFACTION PASS (#78): a breath of weight on the vanish
  for (let k = 0; k < 6; k++) spawnParticle(player.x, player.y - 44, { vy: -50, spread: 220,
    life: 0.8 + Math.random() * 0.5, r: 1.1 + Math.random() * 0.9, color: k % 2 ? '#ffd76a' : '#ffecb0' });
  VEIL.trailT = 0;
  veilSmoke(player.x, player.y - 40, 8);
  SFX.veilOn();
}
function veilEnd() {
  if (veilActive()) {
    if (WRUN.on && WRUN.tAcc && WRUN.tAcc.vT0 !== undefined) { WRUN.tAcc.veilT = +((WRUN.tAcc.veilT || 0) + (gameTime - WRUN.tAcc.vT0)).toFixed(1); WRUN.tAcc.vT0 = undefined; }   // (tele)
    player.vx *= SMOKE_DIL; player.vy *= SMOKE_DIL;   // THE CLEAN EXIT (RABBI-VEIL #8): the speed you SAW is the speed you keep — the exemption un-scales at the door so REAL velocity is continuous (no 2.3× slingshot on stride exits, no 1600px/s slam on dive exits)
    if (gameTime - VEIL.bufJump < 0.3) { spaceJustPressed = true; }   // THE BUFFER (#11): a fresh press survives the ability — re-armed at the door, the engine's own jump rules judge it
    veilSmoke(player.x, player.y - 40, 8);
    rings.push({ x: player.x, y: player.y - 44, age: 0, life: 0.2, maxR: 46, color: '#c9f2ff', wd: 2 });   // THE EXIT SHIMMER (#74): re-materialization reads clean — the vulnerability moment is honest
    for (let k74 = 0; k74 < 4; k74++) spawnParticle(player.x, player.y - 44, { vy: -60, spread: 200, life: 0.3, r: 2, color: '#e6f6ff' });
    SFX.veilOff();
  }
  VEIL.bufJump = -9;
  RBWAR.graceUntil = gameTime + (SANDBOX.on ? SANDBOX.rb.grace : 0.45);   // THE RE-ACQUIRE (RABBI-VEIL #82): re-forming buys a breath before the beams re-lock
  VEIL.exitAt = gameTime;   // GHOSTED's clock (#96)
  VEIL.t = 0;
}
function veilCancelQuiet() {   // THE INSTANT ON (RABBI-VEIL #7): the tap was a STRIKE all along — the newborn veil un-happens: no blast, no spend, the fuse never armed
  player.vx *= SMOKE_DIL;   // THE DASH MARRIAGE (#10): undo the entry scale — entry×(1/DIL) then cancel×DIL is an identity, so a running tap keeps its exact stride
  VEIL.t = 0;
  VEIL.meter = Math.min(VEIL.dur, VEIL.refundM || VEIL.meter);
  SMOKE.trail.length = 0; SMOKE.fuse.length = 0;
  VEIL.bufJump = -9;   // THE BUFFER (#11): a strike tap's outcome is the strike — nothing carries over
  if (VEIL.wasGrounded && player.y > groundY() - 6) { player.y = groundY(); player.vy = 0; player.grounded = true; }   // the stance restored — no phantom landing squash on a strike tap
}
function rmbUp() {   // the judge: a quick lift is the STRIKE, a long hold was the VEIL — but the veil begins ON THE PRESS now (THE INSTANT ON, RABBI-VEIL #7)
  if (SHADOW.holdT < 0) return;
  const wasVeiled = rmbVeiled;
  rmbVeiled = false;
  if (wasVeiled && SHADOW.holdT < RMB_HOLD_T) { veilCancelQuiet(); shadowRelease(); }   // the tap: the newborn veil un-happens and the strike fires
  else if (wasVeiled) { smokeDetonate(); veilEnd(); SHADOW.holdT = -1; }   // re-form — and the road blows behind you
  else if (SHADOW.holdT < RMB_HOLD_T) shadowRelease();
  else SHADOW.holdT = -1;
}          // the step only reaches so far — get close, then vanish
const SHADOW_HOP_T = 0.38;         // each cut plays out before the next hop
const shadowChain = { queue: [], t: 0, ox: 0, oy: 0, returnT: 0 };

// ---- ELECTRIC SHOCK — the other right-click gear: hold to charge, release to arc,
// the bolt takes the closest body then leaps to the next. Q swaps equipment.
// tap = hop + one bouncing bolt; hold = hover & absorb up to 4 shots, release dumps them as chain lightning
const SHOCK = { range: 620, bounce: 430, phase: 'idle', t: 0, absorbed: 0, hover: 0, cd: 0, sparkT: 0, tap: false, air: false, dvx: 0, dvy: 0, juice: 3, autoT: 0, driedAt: -9, reflectsRun: 0, bufJump: -9 };   // autoT/driedAt: THE RIFLE's clock and its dry-click stamp (#25). reflectsRun: THE CAGE'S LIFETIME WORK. bufJump: THE STORM'S BUFFER (cure #2) — a jump pressed mid-bolt is HELD for the door instead of deleted
// (#45) — `SHOCK.reflects` is ZEROED by every disengage, so anything reading it after a cage closes sees 0.
