      if (k === 0) { const r0 = orbRim(mx2, my2); fx2 = r0.x; fy2 = r0.y; }   // THE RIM'S ANSWER (2026-08-24): the salvo's first hop leaves the SHELL toward its mark, never the center; the leaps stay body-to-body
      if (shockArcs.length < 90) shockArcs.push({ x0: fx2, y0: fy2, x1: mx2, y1: my2, age: -(i * stride + k * 0.06), life: 0.26 });   // the LIGHT pools at scale — a mass overload is a show, not a lockup
      shockCascade.push({ e: m, t: 0.02 + i * stride + k * 0.06, orb: true });   // SALVO DAMAGE reads this tag — and the DAMAGE never pools. The HOP delay stays 0.06 uncompressed: it is one bolt's leap between two bodies, a physical span, not a place in the queue
      fx2 = mx2; fy2 = my2;
