    const my2 = reflIs(m) ? m.y - 55 : m === FORGE ? groundY() - FORGE.ALT : groundY() - (m.dy || 0) - 40;   // (#496) the chain can hold the FORGE now — p156: and every roster body at its own chest (the bolt visibly struck the pavement under a flying clone)
    const mx3 = bodyX(m);   // (#496) and his x is CAPITAL -- a NaN endpoint is invisible lightning
    shockArcs.push({ x0: fromX, y0: fromY, x1: mx3, y1: my2, age: -i * 0.09, life: 0.24 });
