  tone({ f0: 1250, f1: 140, dur: 0.3, type: 'sawtooth', vol: 0.085 * big });   // the zap, tearing down
  tone({ f0: 74, f1: 44, dur: 0.26, type: 'sine', vol: 0.13 * big });         // the thump underneath
