    for (const bC56 of REFL_BODIES) if (bC56.on && !bC56.dead && Math.abs(bC56.x - player.x) < 760) cands.push(bC56);   // p156: the sky names every body in the band
    // (#496) THE SURVEY'S OWN FALSE GREEN: TABLE ONE marked the tempest complete because its DOOR
    //   (`hurtBody`) knows every body -- but this list never held the KINGPIN at all, and a bolt cannot
    //   hammer a body that is not in the list. Same 760 band, same one-strike-per-cast grammar.
    if (!boss.dead && boss.engaged && Math.abs(boss.x - player.x) < 760) cands.push(boss);
    if (FORGE.state === 'run' && FORGE.hp > 0 && Math.abs(FORGE.X - player.x) < 760) cands.push(FORGE);
    for (const tS of tears) if (!tS.dead && Math.abs(tS.x - player.x) < 760) cands.push(tS);   // (his order 2026-09-02) the sky bolts hammer the wounds too — same band, same one-strike grammar
    cands.sort((a, b) => (marked.has(a) ? 1 : 0) - (marked.has(b) ? 1 : 0));
