      const dly = 0.08 + i * 0.1;
      shockArcs.push({ x0: ex + (Math.random() - 0.5) * 170, y0: ey - 990, x1: ex, y1: ey, age: -dly, life: 0.3 });
      rings.push({ x: ex, y: ey, age: -dly, life: 0.2, maxR: 58, color: '#ffffff', wd: 4 });
      rings.push({ x: ex, y: ey, age: -dly - 0.03, life: 0.3, maxR: 95, color: '#ffe27a', wd: 3 });
