    ctx.fillStyle = '#6eb5ff'; ctx.fillRect(xB, yB, wB * fB, hB);   // the charge — BLUE (his recolor, 2026-09-01: 'electric should have been blue'; the store's gold stays the store's), lifted 20% toward white
    if (fB > 0.02) { ctx.fillStyle = 'rgba(255,255,255,0.9)'; ctx.fillRect(xB + wB * fB - 1, yB, 1, hB); }   // the hot tip
