          const frC = Math.max(0, Math.min(1, (player.dashCharges === undefined ? 0 : player.dashCharges) - fP));
          if (frC > 0.03) { ctx.fillStyle = 'rgba(177,245,255,0.8)'; ctx.fillRect(xP - 3, yP + 3 - 6 * frC, 6, 6 * frC); }
