    floaters.push({ lane: 'combat', pr: 1, x: t.x, y: groundY() - t.dy - 130, text: 'DODGED', age: 0 });
    tone({ f0: 420, f1: 200, dur: 0.1, type: 'sine', vol: 0.06 });
