  if (Math.abs(player.x - vendor.x) > 110 ||
      Math.abs((groundY() - player.y) - vendor.dy) > 70) return;
  if (u.lv >= u.vals.length - 1) {
    floaters.push({ lane: 'ticker', pr: 1, x: player.x, y: player.y - 120, text: u.label + ' MAXED', age: 0 });
    return;
  }
  const cd = masteryCost(u.costD[u.lv], table, table === SHADOW_UP ? 0.16 : 0.12);   // shadow runs HOT
  if (diamondBalance() < cd) {
    floaters.push({ lane: 'ticker', pr: 1, x: player.x, y: player.y - 120, text: 'DIAMONDS ONLY — NEED ◆' + cd, age: 0 });
    tone({ f0: 220, f1: 150, dur: 0.12, type: 'square', vol: 0.06, cue: 'pilot' });   // THE RED MODE'S ISSUES (RED-2): the mastery till's NO is his own feedback, never crowd - under the guard it played 1 in 4
    return;
  }
  diamondsSpent += cd;
  u.lv++;
