    ctx.beginPath();
    ctx.moveTo(-tw, yT); ctx.lineTo(tw, yT); ctx.lineTo(uw, yU); ctx.lineTo(hw, yG);
    ctx.lineTo(lw, yL); ctx.lineTo(0, yP); ctx.lineTo(-lw, yL); ctx.lineTo(-hw, yG); ctx.lineTo(-uw, yU);
    ctx.closePath(); ctx.clip();
