      const sxF = (t.x - camX) * WORLD_ZOOM + Wn9 / 2, syF = (cyF - camY - Hn9) * WORLD_ZOOM + Hn9, hhF = t.h / 2 * WORLD_ZOOM;
      const onF = Math.abs(sxF - Wn9 / 2) <= Wn9 / 2 + 20 * WORLD_ZOOM && syF + hhF >= 60 && syF - hhF <= Hn9 - 60;
      TEARPTRQ.push({ wx: t.x, wy: cyF, h: t.h, dy: t.dy, on: onF, aM: aM9, seed: t.seed });
