function applyJetUp(k) {
  const u = JET_UP[k], v = u.vals[u.lv];
  if (k === 'rack') { FLARES.max = v; FLARES.n = Math.min(FLARES.n, v); return; }
  if (k === 'reflex') { FLARES.reflex = v; return; }
  // ⚠ (#391) **THREE OF THESE BRANCHES STILL HAVE NO ROW, AND THAT IS A MISSING RUNG, NOT A DEAD BRANCH -
  //   THE TWO WANT OPPOSITE CURES.** `tank`, `regen` and `over` have no `JET_UP` entry, so they are never
  //   applied and their cells sit at the shipped `JET = { tank: 1, regen: 1, spd: 0 }`. **THE ORPHAN
  //   CLAUSE DOES NOT REACH THEM: its bar is absence of the SUBJECT, and all three subjects exist and are
  //   read every frame** - `player.fuel = P.fuelMax.v * JET.tank` at the run door and again at the refill,
  //   `P.fuelRegen.v * JET.regen` in the regen line, and `P.jetBoostSpd.v + JET.spd` in the run-speed
  //   line, which is currently adding a permanent +0 to the afterburn top speed. Deleting the branches
  //   would delete three finished effects to tidy a table.
  //   **RULED: they keep their branches and they are OWED ROWS, priced in their own stone.** `scorch`
  //   above is this stone's one rung because it is the only one of the four whose cell is a DAMAGE source
  //   that does nothing at its default; a fuel tank at x1 and a top speed at +0 are neutral, not broken,
  //   and three more priced rungs in one copy-fix stone is an economy change wearing a cleanup's clothes.
  //   Filed as its own line rather than done badly here.
  if (k === 'tank') JET.tank = v;
  else if (k === 'regen') JET.regen = v;
  else if (k === 'over') JET.spd = v;
  else if (k === 'dive') JET.dive = v;
  else if (k === 'meteor') JET.meteor = v;
  else if (k === 'legs') DUMP.legs = v;   // (#392) the gunship's own stance owns the cell, not `JET`
}
