function drawEmeraldGem(x, y, r, gemIdx, t) {
  const hue = 202;   // ONE color — ice-white diamond, whatever the caller thought it was minting
  const rr = r * 0.8;   // smaller — the ruling
  if (LOOTLAB.probe) LOOTLAB.draws.push({ hue, r: +rr.toFixed(2) });
  // (watches/chains never route here — drawLootStyle owns the milestone loot, WAVE-ORDER #7)
  const w = rr * 1.05, h = rr * 1.05, c = rr * 0.42;
  ctx.save();
  ctx.translate(x, y);
  const cut = (sc) => {
    ctx.beginPath();
    ctx.moveTo(0, -h * sc); ctx.lineTo(w * sc - c * sc, -c * sc * 0.6);
    ctx.lineTo(w * sc * 0.62, h * sc * 0.9); ctx.lineTo(-w * sc * 0.62, h * sc * 0.9);
    ctx.lineTo(-w * sc + c * sc, -c * sc * 0.6);
    ctx.closePath();
  };
  const grad = ctx.createLinearGradient(0, -h, 0, h);
  grad.addColorStop(0, 'hsl(' + hue + ', 55%, 88%)');
  grad.addColorStop(0.45, 'hsl(' + hue + ', 65%, 62%)');
  grad.addColorStop(1, 'hsl(' + hue + ', 60%, 34%)');
  ctx.fillStyle = grad;
  ctx.strokeStyle = 'hsla(' + hue + ', 60%, 22%, 0.9)';
  ctx.lineWidth = 1.2;
  cut(1); ctx.fill(); ctx.stroke();
  // crown facets
  ctx.strokeStyle = 'hsla(' + hue + ', 70%, 92%, 0.55)';
  ctx.lineWidth = 0.9;
  ctx.beginPath();
  ctx.moveTo(0, -h); ctx.lineTo(0, h * 0.9);
  ctx.moveTo(-w + c, -c * 0.6); ctx.lineTo(w - c, -c * 0.6);
  ctx.moveTo(-w * 0.62, h * 0.9); ctx.lineTo(0, -c * 0.6); ctx.lineTo(w * 0.62, h * 0.9);
  ctx.stroke();
  // live fire — the brilliant sweep, clipped to the cut
  ctx.save();
  cut(1); ctx.clip();
  ctx.rotate(-0.5);
  const sw2 = Math.sin(t * 2.9 + x * 0.09) * w * 1.3;
  ctx.fillStyle = 'rgba(255,255,255,0.22)';
  ctx.fillRect(sw2 - 5, -h * 2, 10, h * 4);
  ctx.fillStyle = 'rgba(255,255,255,0.45)';
  ctx.fillRect(sw2 - 1.2, -h * 2, 2.4, h * 4);
  ctx.restore();
  // A REAL SPARKLE — four rays, firing often, scaled to the stone
  const twk = Math.max(0, Math.sin(t * 4.1 + x * 0.31));
  if (twk > 0.35) {
    const a = (twk - 0.35) / 0.65;
    const sx = w * 0.4, sy = -h * 0.45, sr = rr * (0.45 + 0.4 * a);
    ctx.strokeStyle = 'rgba(255,255,255,' + (0.9 * a) + ')';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(sx - sr, sy); ctx.lineTo(sx + sr, sy);
    ctx.moveTo(sx, sy - sr); ctx.lineTo(sx, sy + sr);
    ctx.moveTo(sx - sr * 0.55, sy - sr * 0.55); ctx.lineTo(sx + sr * 0.55, sy + sr * 0.55);
    ctx.moveTo(sx - sr * 0.55, sy + sr * 0.55); ctx.lineTo(sx + sr * 0.55, sy - sr * 0.55);
    ctx.stroke();
    if (LOOTLAB.probe && LOOTLAB.draws.length) LOOTLAB.draws[LOOTLAB.draws.length - 1].sparkleRays = 4;
  }
  ctx.restore();
}

// a diamond drawn by hand — brilliant-cut profile with live facets and a twinkle.
// gemIdx picks the stone: 0/1 ice-white, 2 champagne gold. Used for the world diamonds.
function drawDiamond(x, y, r, gemIdx, t) {
  const hue = gemIdx === 2 ? 46 : 197;
  const sat = gemIdx === 2 ? 78 : 72;
  const tw = r * 0.58;             // table half-width
  const ch = r * 0.52;             // crown height above the girdle
  const ph = r * 1.02;             // pavilion depth to the culet
  ctx.save();
  ctx.translate(x, y);
  // body
  const grad = ctx.createLinearGradient(0, -ch, 0, ph);
  grad.addColorStop(0, 'hsl(' + hue + ', ' + sat + '%, 94%)');
  grad.addColorStop(0.45, 'hsl(' + hue + ', ' + sat + '%, 72%)');
  grad.addColorStop(1, 'hsl(' + hue + ', ' + (sat - 8) + '%, 48%)');
  ctx.fillStyle = grad;
  ctx.strokeStyle = 'hsla(' + hue + ', 60%, 30%, 0.9)';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(-tw, -ch); ctx.lineTo(tw, -ch);      // table
  ctx.lineTo(r, 0); ctx.lineTo(0, ph);            // girdle → culet
  ctx.lineTo(-r, 0); ctx.closePath();
  ctx.fill(); ctx.stroke();
  // facet lines
  ctx.strokeStyle = 'hsla(' + hue + ', 55%, 38%, 0.55)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(-tw, -ch); ctx.lineTo(-r * 0.34, 0); ctx.lineTo(0, ph);
  ctx.moveTo(tw, -ch);  ctx.lineTo(r * 0.34, 0);  ctx.lineTo(0, ph);
  ctx.moveTo(-r, 0); ctx.lineTo(r, 0);
  ctx.stroke();
  // live shimmer — one crown facet catches the light, swapping sides
  const sh = Math.sin(t * 5.2 + x * 0.13);
  ctx.fillStyle = 'rgba(255,255,255,' + (0.16 + 0.22 * Math.abs(sh)) + ')';
  ctx.beginPath();
  if (sh > 0) { ctx.moveTo(tw, -ch); ctx.lineTo(r, 0); ctx.lineTo(r * 0.34, 0); }
  else        { ctx.moveTo(-tw, -ch); ctx.lineTo(-r, 0); ctx.lineTo(-r * 0.34, 0); }
  ctx.closePath(); ctx.fill();
  // twinkle — a 4-point star that breathes on the crown edge
  const twk = Math.max(0, Math.sin(t * 3.1 + x * 0.31));
  if (twk > 0.55) {
    const a = (twk - 0.55) / 0.45;
    const sx = -tw * 0.6, sy = -ch * 0.85, sr = r * (0.32 + 0.3 * a);
    ctx.strokeStyle = 'rgba(255,255,255,' + (0.85 * a) + ')';
    ctx.lineWidth = 1.3;
    ctx.beginPath();
    ctx.moveTo(sx - sr, sy); ctx.lineTo(sx + sr, sy);
    ctx.moveTo(sx, sy - sr); ctx.lineTo(sx, sy + sr);
    ctx.stroke();
  }
  ctx.restore();
}
