function summonWave(n, sky) {
  // THE KINGPIN'S LAW: he summons DRONES and nothing else — a sky that hunts
  const droneAlive = enemies.filter(e => e.drone && e.summoned && e.state !== 'die').length;
  // THE ROOF CAME UP, 26 -> 85 (BOOK II #82, v1.6.679). THE CEILING STAYS; only the number moved.
  // DERIVED FROM HIS OWN DESIGN STATEMENT rather than from taste: `boss.summonBudget` is the kingpin's
  // LIFETIME allowance and it is the number that says how many men he has — 30 at spawn, 40 on reset,
  // +45 on the rage line, so 85 is the largest allowance he can ever hold. Setting the alive-at-once
  // ceiling TO that maximum means it can never bind before his own written allowance does: he can now
  // put every man he has in the sky at once, which is what the sentence "LAST OF MY MEN!" already
  // promises. The clause survives as a backstop against a negative `n`, not as a second hidden limit.
  // The old 26 was a bare unnamed literal with no dial, no caption and no derivation anywhere near it.
  n = Math.min(n, boss.summonBudget, Math.max(0, 85 - droneAlive));
  for (let k = 0; k < n; k++) {
    const dx0 = boss.x + (Math.random() - 0.5) * 1000;
    const alt = (sky ? Math.max(300, boss.dy - 220) : 240) + Math.random() * 380;
    spawnDrone(dx0, alt, dx0 - 300, dx0 + 300, true);
    enemies[enemies.length - 1].hunter = true;   // they don't patrol — they COME
    boss.summonBudget--;
    for (let j2 = 0; j2 < 5; j2++) {
      spawnParticle(dx0, groundY() - alt - 40, { vy: -60, spread: 140, life: 0.4, r: 3, color: j2 % 2 ? '#9f5af0' : '#d0b0ff' });
    }
  }
  if (n > 0) {
    tone({ f0: 200, f1: 90, dur: 0.4, type: 'sawtooth', vol: 0.12 });
    shake = Math.min(shake + 4, 12);
  }
}
