// inside the tuning wing rather than failing a law cleanly, which is `PBUDGET`'s own recorded reason.
let BL_ALT_M = 1;
function spawnBlimp(cx, alt) {
  SFX.arrive('machines', cx);   // (#174) THE ARRIVAL VOICE — pooled, so a squad rings once
  const plat = { x: cx - 105, w: 210, dy: alt, kind: LAUNCHERS_ENABLED ? 'prop' : 'blimp', blimpPlat: true, desertLand: true };   // THE BLIMP RULING (#227): architecture is standable wherever it exists — this is the whole revert
  platforms.push(plat);
  const dir = Math.random() < 0.5 ? -1 : 1;
  const b = { x: cx, baseAlt: alt, dy: alt, dir,
              face: dir, turnT: -1,               // turn animation: -1 idle, else 0..TURN_DUR
              x0: cx - 450, x1: cx + 450, bob: Math.random() * 6.28, plat,
              launcherDead: !LAUNCHERS_ENABLED };  // no rig yet — the deck is open
  blimps.push(b);
  if (LAUNCHERS_ENABLED) enemies.push({
    launcher: true, blimpRef: b, x: cx, dy: alt, hp: scaleHp(6),
    type: 0, dir: 1, state: 'ready', t: 0, anim: 'idle', animTime: 0,
    threw: false, cooldown: 2.5 + Math.random() * 2, fade: 0, lockT: 0,
  });
}
