function spawnArmada() {
  SFX.arrive('machines', player.x);   // (#174) THE ARRIVAL VOICE — pooled, so a squad rings once
  if (blimps.length) return;
  const span = STREET_MAX - STREET_MIN - 2400;
  // stratified altitudes — rooftop height up to above the tallest spire — dealt out shuffled
  const alts = [];
  for (let i = 0; i < BLIMP_COUNT; i++) alts.push(720 + (i / (BLIMP_COUNT - 1)) * 1770 + Math.random() * 80);
  for (let i = alts.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); const t = alts[i]; alts[i] = alts[j]; alts[j] = t; }
  for (let i = 0; i < BLIMP_COUNT; i++) {
    spawnBlimp(STREET_MIN + 1200 + span * (i + 0.5) / BLIMP_COUNT, alts[i]);
  }
}

// ════════════════════════════════════════════════════════════════════════════════════════════
// THE DRIFT EXEMPTION (BOOK II #228) — **A BLIMP IS UNDER POWER, AND ITS 55 px/s IS A THROTTLE.**
// ════════════════════════════════════════════════════════════════════════════════════════════
// THE PREMISE IS CONFIRMED, NOT ASSUMED: this function reads `WIND` exactly ZERO times, and moves the
// fleet on a private hardcoded `b.dir * 55 * dt`. That is the shape `[WND]` killed at STAGECRAFT #2 —
// **a private breeze** — and the order is right that leaving it silent is inadmissible.
//
// **IT IS EXEMPT, AND #227 IS WHY.** THE BLIMP RULING settled that a blimp is ARCHITECTURE, and this is
// the half that ruling implies: **weather moves what cannot move itself.** An airship with propellers,
// prop-wash and a come-about is the one thing on this stage that decides its own heading. A cloud drifts
// because it has no choice; a blimp holds a course. Putting the fleet on `WIND.v` would not be more
// honest physics, it would be a claim that twenty powered ships have no engines.
//
// **AND THE EXEMPTION IS THE CHEAPER ANSWER ON FOUR MEASURED COUNTS, each checkable in one grep:**
//   1. `[OW]` rung 4 fails any newly-registered atmosphere table whose anchor sits outside every fence.
//      THE ATMOSPHERE REGION runs `game.js` 24894–27749; the blimp system sits at 24297–24377,
//      **entirely before it.** A wind coefficient with a dial would red by construction, on its first run.
//   2. THE FX page's `windM` note enumerates **EIGHT** named riders of THE ONE WIND, by name, as a count.
//      **A ninth rider makes a shipped caption false the moment it lands** — THE CAPTION LIE's own class,
//      priced once on this floor at 42% of a pilot's damage.
//   3. This region rolls raw `Math.random()` FIVE times. Legal today because blimps are the WAR's;
//      **the instant they are declared weather those five become THE TWO STREAMS LAW crimes**, because a
//      roll the atmosphere spends shifts every seed-locked run's combat dice.
//   4. `updateBlimps(dt)` runs at :20774 and `windTick` inside `updateSky(dt)` at :20780 — **six lines
//      later.** A wind read here is always one frame stale, so the fleet would ride yesterday's gust.
//
// **WHAT WOULD REOPEN THIS, written down so a later stone does not have to guess:** if the fleet ever
// loses power — a wreck, a drifting hulk, a ship whose engines are cut — that body is no longer under
// power and the exemption does not cover it. It would ride `WIND.v` signed, on `vultTick`'s precedent,
// and it would owe all four of the costs above. **The exemption is about ENGINES, not about blimps.**
function updateBlimps(dt) {
  for (const b of blimps) {
    const prevX = b.x, prevDy = b.plat.dy;
    b.bob += dt;
    if (b.turnT >= 0) {                    // coming about — she pivots, barely drifting
      b.turnT += dt;
      if (b.turnT >= BL_TURN) { b.turnT = -1; b.face = b.dir; }
    } else {
      b.x += b.dir * 55 * dt;   // THE THROTTLE, not a breeze — THE DRIFT EXEMPTION above, ruled at #228 on #227's architecture ruling
    }
    if (b.x < b.x0) { b.x = b.x0; if (b.dir !== 1)  { b.dir = 1;  b.turnT = 0; } }
    if (b.x > b.x1) { b.x = b.x1; if (b.dir !== -1) { b.dir = -1; b.turnT = 0; } }
    b.dy = b.baseAlt + Math.sin(b.bob * 0.9) * 12;
    b.plat.x = b.x - 105;
    b.plat.dy = b.dy;
    // the fence rides his ship — crate and board track the deck
    for (const v of [shadowBroker, stormDealer, jetMechanic]) {
      if (v.seeded && v.blimp === b) { v.x = b.x; v.dy = b.plat.dy; }
    }
    // prop wash — pale exhaust streaming off the tail, only when she's under way and on screen
    if (b.turnT < 0 && Math.abs(b.x - camX) < 1000 && Math.random() < 0.5) {
      if (particles.length >= PBUDGET) particles.shift();
      particles.push({
        x: b.x - b.dir * 141 + (Math.random() - 0.5) * 8,
        y: groundY() - b.plat.dy - 119 + (Math.random() - 0.5) * 78,
        vx: -b.dir * (200 + Math.random() * 160),
        vy: (Math.random() - 0.5) * 46,
        life: 0.32, age: 0, r: 2.1, color: '#cfe3f5',
      });
    }
    // carry the rider — horizontal drift AND the bob
    if (player.grounded && Math.abs(player.y - (groundY() - prevDy)) < 4 &&
        player.x > b.plat.x - 14 && player.x < b.plat.x + b.plat.w + 14) {
      player.x += b.x - prevX;
      player.y = groundY() - b.plat.dy;
    }
  }
}

