// diamond rain — they fall from the sky and settle wherever they land
const rainDrops = [];
let rainQueue = 0, rainT = 0;
function updateRain(dt) {
  if (rainQueue > 0) {
    rainT -= dt;
    if (rainT <= 0) {
      rainT = 0.014;
      rainQueue--;
      rainDrops.push({
        x: STREET_MIN + 150 + Math.random() * (STREET_MAX - STREET_MIN - 300),
        y: groundY() - 2400 - Math.random() * 900,
        vy: 480 + Math.random() * 320, vx: (Math.random() - 0.5) * 70, spin: Math.random() * 6.28,
      });
    }
  }
  for (let i = rainDrops.length - 1; i >= 0; i--) {
    const d = rainDrops[i];
    const prevY = d.y;
    d.y += d.vy * dt; d.x += d.vx * dt; d.spin += dt * 7;
    let landAt = null;
    if (prevY <= groundY() && d.y >= groundY()) landAt = 0;
    for (const p of platforms) {
      if (!platCatchesRain(p)) continue;   // (#223) was a four-kind list; the derivation carries the same four
      const py = groundY() - p.dy;
      if (prevY <= py && d.y >= py && d.x > p.x && d.x < p.x + p.w) {
        if (landAt === null || p.dy > landAt) landAt = p.dy;
      }
    }
    if (landAt !== null) {
      dropGems(d.x, landAt, 1);
      for (let k = 0; k < 5; k++) spawnParticle(d.x, groundY() - landAt, { vy: -90, spread: 160, life: 0.4, r: 2.5, color: '#8fe8ff' });
      rainDrops.splice(i, 1);
      updateMissionHud();
    }
  }
}

