  RIMA: 0.26,        // the sunward catch-light on each crown, offset along the ONE vector
  BREATHS: [[1.185, 0.0833], [1.1682, 0.0909], [1.1514, 0.1], [1.1345, 0.1111], [1.1177, 0.125],
    [1.1009, 0.1429], [1.0841, 0.1667], [1.0673, 0.2], [1.0505, 0.25], [1.0336, 0.3333],
    [1.0168, 0.5], [1, 1]],
