  p.vy = opts.vy + (rnd4() - 0.5) * 60;
  p.life = opts.life || 0.35;
  p.age = 0;
  p.r = opts.r || 4 + rnd4() * 3;
  p.color = opts.color;
  p.grav = opts.grav || 0;
