      const iBF = aBF.loop ? (Math.floor(player.animTime * aBF.fps) % nBF + nBF) % nBF : Math.min(nBF - 1, Math.floor(player.animTime * aBF.fps));
      const hitBF = bfFrame(aBF.frames[iBF]);
