  ctx.fillStyle = 'rgba(18,20,40,0.92)'; ctx.fill();
  roundRect(ctx, sbx, sby, sbw, sbh, 12);
  ctx.lineWidth = 2; ctx.strokeStyle = 'rgba(232,210,123,' + (0.55 + pulse * 0.45).toFixed(3) + ')'; ctx.stroke();
  tutSlabText('start', 'START TUTORIAL', ts > 1 ? 30 : 18, '700', W / 2, sby + (ts > 1 ? 44 : 32), '#ffe9a3', sbw - 24);
  tutSlabText('start-cap', TOUCH_MODE ? (ts > 1 ? 'walk, fly, dash, shoot. Tap to train.' : 'FULL KIT LIVE — walk, fly, dash, shoot. Tap to train.') : 'FULL KIT LIVE — walk, fly, dash, shoot. ENTER works too.', ts > 1 ? 24 : 11, '', W / 2, sby + (ts > 1 ? 84 : 56), 'rgba(255,255,255,0.72)', sbw - 24);   // (v1.6.1510) a phone reads the four verbs and the tap; FULL KIT LIVE is the desk's
  const bw = ts > 1 ? 260 : 210, bh2 = ts > 1 ? 60 : 44;
