  const hold9 = (typeof storyHold9 === 'function') && storyHold9();   /* THE WORLD HOLDS FOR THE TEXT (2026-09-20) */
  if (!paused && !shopOpen && !hold9) update(dt * dil * govD, dt); else if (hold9 && !shopOpen) story1HoldTick(dt * dil * govD);   // THE REFEREE'S CLOCK: the world gets `dt * dil`, and the REAL dt rides beside it — `frameInner` is the only place that knows both, so the referees are HANDED the truth instead of re-deriving it from a chain that can go stale mid-frame
  if (!paused && !shopOpen && !hold9) { GOV.upMs = performance.now() - __mT0; GOV.upRan = true; } else GOV.upRan = false;   // THE THINKING HALF's wall time (v1.6.1419) - the wiretap's `up`, measured by the game itself; THE RED LATCH clears on this alone (govGuard reads it next frame, above update)
  draw();
  const __mW = performance.now() - __mT0;
  FRAMEX.lastW = __mW; FRAMEX.lastUp = GOV.upRan ? GOV.upMs : 0; FRAMEX.birdsLast = FRAMEX.birds; FRAMEX.birds = 0;   // (v1.6.1559) THE FRAME'S ANATOMY: this frame's wall halves and the birds it painted, read by the next frame's books
  METER.ms += (__mW - METER.ms) * 0.1;
  hitchRecord(__mW);   // THE HITCH LEDGER (HITCH-HUNT #1): every frame's true wall cost, on the record
  govTick(__mW, rawDt);   // THE GOVERNOR TIERS: YELLOW reads the wall frame the meter just priced; RED is the guard above
  govLedger(__mW, rawDt);
  if (ARENA9_ON()) { if (!paused) arenaTick9(dt); arenaDrawUi9(); }   // THE ARENA (2026-09-24): the commanders' clock and the panel's face
