  if (mission.state === 'playing' && !dead && !(tutorialScreen && TITLE9.on) && !ARENA9_ON()) glassSurface(paused ? 'pause' : null);   // THE ARENA draws its own strip   // (v1.6.1582) the glass strip never paints over the title screen
