function hintSay9(id, text) { if (!HINTS9.armed || HINTS9.seen[id] || HINTS9.cur) return false; HINTS9.seen[id] = true; HINTS9.cur = { id, text: String(text), age: 0 }; HINTS9.shown++; return true; }
function hintsPassed9() { HINTS9.armed = false; HINTS9.cur = null; try { localStorage.setItem('arena_hinted', '1'); } catch (e) { /* session only */ } }
