  if (!HINTS9.seen.move) { hintSay9('move', 'WALK WITH ' + tk('left') + ' / ' + tk('right') + (TOUCH_MODE ? ' \u2014 TAP ' + tk('jump') + ' TO JUMP' : ' \u2014 JUMP WITH ' + tk('jump'))); return; }
  if (near && !HINTS9.seen.shoot) { hintSay9('shoot', (TOUCH_MODE ? 'SHOOT \u2014 TAP ' + tk('pulse') : 'SHOOT \u2014 ' + tkm('LEFT CLICK', 'pulse')) + '. STAND BACK, THE SHOTS HOME IN'); return; }
  if (hearts < HINTS9.h0 && !HINTS9.seen.hurt) { hintSay9('hurt', 'A HEART GONE \u2014 KEEP MOVING, JUMP OVER THE LEAD'); return; }
  if (runKills > 0 && !HINTS9.seen.gems) { hintSay9('gems', '\u25c6 DIAMONDS DROP FROM THE DEAD \u2014 WALK OVER THEM, SPEND THEM AT THE SHOP'); return; }
  if (dealer && !HINTS9.seen.dealer) { hintSay9('dealer', 'THE DEALER SHOOTS \u2014 JUMP HIS LEAD, SHOOT HIM FIRST'); return; }
  if ((WRUN.runT || 0) > 9 && !HINTS9.seen.dbl) { hintSay9('dbl', 'TAP ' + tk('jump') + ' TWICE \u2014 THE DOUBLE JUMP'); return; }
