function currentFrame() {
  const a = ANIM[player.anim] || ANIM.idle;
  const len = a.frames.length;
  let idx = Math.floor(player.animTime * a.fps);
  // (#146) THE BACKPEDAL. With BACKFIRE armed the facing points at the threat while the legs carry the pilot
  // AWAY, and the run cycle would otherwise play toward the facing — a MOONWALK, photographed and graded at
  // `gallery/stone-179/MOONWALK-GRADE.png`: the legs stride one way while the ground scrolls the other, and a
  // stranger calls that broken (THE PRESENCE LAW clause 4). **The cure is one negation and it needs no new
  // art:** run the cycle BACKWARD, which is what moving against your own facing looks like. The line below
  // already says `handles negatives`, so the machinery was here all along. Only `run` is reversed — the
  // ground locomotion cycle; reversing `jet`, `fall` or `idle` would be meaningless or wrong.
  if (BFST.on && BFST.stance === 'shoulder' && player.anim === 'run') idx = -idx;
  if (!Number.isFinite(idx)) idx = 0;
  if (a.loop) idx = ((idx % len) + len) % len;    // handles negatives
  else idx = Math.min(Math.max(idx, 0), len - 1);
  return SPRITE_META[a.frames[idx]];
}

