function noteFor(id) {   // 'tune.<page>.<row>' | 'arm.<TAG>.<key>' | a NOTES.reg key
  if (!id) return null;
  if (NOTES.reg[id]) return NOTES.reg[id];
  const p = id.split('.');
  if (p[0] === 'tune') { const r = tuneFind(p[1], p[2]); return r ? { name: r.label, cap: r.cap, note: r.note } : null; }
  if (p[0] === 'arm') {   // THE ARSENAL NOTES (DIAL-NOTES #2): prose from the entry, numbers from the LIVE ladder — the note can never lie or go stale
    const L = WAVE_LADDERS.find((l) => l.tag === p[1]); const u = L && L.table()[p[2]];
    if (!u) return null;
    const maxLv = u.vals.length - 1;
    const costs = u.costD, mark = '◆';   // (G33) ONE CURRENCY
    const live = 'Now ' + u.vals[u.lv] + ' (rung ' + u.lv + '/' + maxLv + ')'
      + (u.lv < maxLv ? ' · next ' + u.vals[u.lv + 1] + (costs && costs[u.lv] !== undefined ? ' at base ' + mark + costs[u.lv] + ' before the mastery tax' : '') : ' · MAXED')
      + ' · the whole ladder: ' + u.vals.join(' → ') + '.';
    return { name: p[1] + ' — ' + u.label, cap: u.desc, note: (u.note ? u.note + ' ' : '') + live };
  }
  return null;
}
function noteText(id) { const n = noteFor(id); if (!n || !n.note) return ''; return typeof n.note === 'function' ? n.note() : n.note; }
// THE ROW FIT (#86 THE SKY PAGE): a tuning row prints its CAPTION left and its CEILING right on ONE
// shared baseline, and for four books nothing checked that the two fit. The first photograph ever taken
// of a dial page (ui:true, D065's flag, first real use) showed them printed ON TOP OF EACH OTHER on
// nine of the eleven visible atmosphere rows — "0 strips him to the bodyyo(FULL-SHIP#s#28)" — and the
// census then found 147 of 290 rows across the whole wing doing it. No law saw it: [T10] measures the
// NOTE's wrap inside the ⓘ panel, never the row's own two strings, so a green gate and a garbled page
// coexisted. Neither string may give way — THE CAPTION LAW wants the whole plain line, and THE
// BREATHING ROOM LAW (ARMORY #2) calls a silent clamp a capital crime — so the ROW grows instead: the
// ceiling drops to its own baseline and the row pays 12px. Measured on noteWrap's own 6.2px-per-char
// budget, the file's established deterministic monospace ruler, so the law asks this one function the
