    // pilot's line at 0), farthest first; the lanes NEARER the camera than his line draw after his body - the front pass sits
    // right after the pilot's draw. npcBands 0 (the sims) is the one band it always was, in spawn order.
    const back9 = STORY_STAGE.npcBands ? peds.filter(p9 => pedBandY(p9) <= 0).sort((a9, b9) => pedBandY(a9) - pedBandY(b9)) : peds;
    for (const p of back9) drawPedBody(p);
