      const chg9 = d9.alive ? Math.max(0, 1 - Math.min(1, d9.t / (kind9 === 'relay' ? (d9.hot ? 2 : 4) : kind9 === 'divers' ? (d9.hot ? 4 : 6) : (d9.hot ? 2.5 : 4)))) : 0;   // the charge toward the next spit (the relay's next ping)
