      ctx.fillStyle = d9.alive ? '#3a4356' : '#26292f'; ctx.fillRect(bx9 - 48, by9 - 64, 96, 10); ctx.fillRect(bx9 - 48, by9 - 16, 96, 6); ctx.fillRect(bx9 - 52, by9 - 8, 104, 8);   // the lid, the skirt, the feet
