      if (d9.alive) { const pul9 = 0.5 + 0.5 * Math.sin(gameTime * 2 + bx9 * 0.01); ctx.fillStyle = 'rgba(' + rgb9 + ',' + (0.09 + pul9 * 0.07).toFixed(3) + ')'; ctx.fillRect(bx9 + 26, by9 - 1160, 16, 1050); ctx.fillStyle = 'rgba(' + rgb9 + ',' + (0.3 + pul9 * 0.2).toFixed(3) + ')'; ctx.fillRect(bx9 + 32, by9 - 1160, 4, 1050); }   /* THE DISTRICT (2026-09-20): a beacon column over every standing machine - the light over a machine is the machine */
      if (d9.alive) { ctx.fillStyle = 'rgba(0,0,0,0.6)'; ctx.fillRect(bx9 - 44, by9 - 128, 88, 8); ctx.fillStyle = d9.hot ? '#ff8f88' : '#ffd76a'; ctx.fillRect(bx9 - 43, by9 - 127, Math.max(0, 86 * d9.hp / d9.max), 6); }
      ctx.font = '800 19px ui-monospace, Menlo, monospace'; ctx.textAlign = 'center'; ctx.strokeStyle = 'rgba(0,0,0,0.7)'; ctx.lineWidth = 5;
      const name9 = kind9 === 'relay' ? 'THE RELAY' : kind9 === 'divers' ? 'DIVER HIVE' : 'EYE DISPENSER';
