      /* p178: the SOLD OUT sign wears the same world-unit edge clamp as the live sign above */
      const hfS = ctx.measureText('SOLD OUT — GOOD HUNTING').width / 2 + 18;
      const hvS = (window.innerWidth / 2) / WORLD_ZOOM;
