let TOUCH_MODE = frameTouchGlass();
const PHONE_TRIGGER = { on: TOUCH_MODE, why: TOUCH_MODE ? 'touch' : 'desk' };   // (v1.6.1526) THE PHONE FIRES BY ITSELF - his word 2026-09-17 ('auto fire on the phone makes sense'): ON for every touch glass, the pulse fires by itself at a foe ahead while the thumbs steer and jump; a desk keeps its trigger; ?autofire=0 turns it off, ?autofire=1 forces it on
try { if (!globalThis.__SIM__ && typeof localStorage !== 'undefined') { const a9 = localStorage.getItem('arena_autofire'); if (a9 === '0') { PHONE_TRIGGER.on = false; PHONE_TRIGGER.why = 'menu:off'; } else if (a9 === '1') { PHONE_TRIGGER.on = true; PHONE_TRIGGER.why = 'menu:on'; } } } catch (e9) { }   // (v1.6.1570) THE AUTO FIRE TOGGLE - his order 2026-09-19 ('in the options menu, you can put a toggle for auto fire'): the player's pick lives in the vault as trax_autofire ('0' off, '1' on), read once at boot (only a touch glass ever writes it, and the phone's trigger needs TOUCH_MODE anyway - so a touch laptop that boots as a desk and wakes its thumbs on the first finger keeps the pick too); the ?autofire= address switch below keeps the last word (the rig's door); absent or garbage reads as his default, ON
function phoneTriggerSet(v) { PHONE_TRIGGER.on = !!v; PHONE_TRIGGER.why = v ? 'menu:on' : 'menu:off'; try { if (typeof localStorage !== 'undefined') localStorage.setItem('arena_autofire', v ? '1' : '0'); } catch (e) { /* session only */ } return PHONE_TRIGGER.on; }   // (v1.6.1570) THE MENU'S DOOR for the toggle: one flag, written on every flip
try { if (!globalThis.__SIM__ && typeof location !== 'undefined') { if (/[?&]autofire=0(&|$)/.test(location.search)) { PHONE_TRIGGER.on = false; PHONE_TRIGGER.why = 'autofire=0'; } else if (/[?&]autofire=1(&|$)/.test(location.search)) { PHONE_TRIGGER.on = true; PHONE_TRIGGER.why = 'autofire=1'; } } } catch (e9) { }
function phoneFoeAhead9() {   // (v1.6.1525) pure over the field: a live hostile in FRONT of the pilot within the pulse's reach - the bolt homes, so any height counts; the first found ends the walk
  const fx9 = player.facing > 0 ? 1 : -1;
  for (let i = 0; i < enemies.length; i++) { const e = enemies[i]; if (e.state === 'die' || allyBody(e)) continue; const dx = (e.x - player.x) * fx9; if (dx > 0 && dx < PULSE_RANGE) return true; }
  return false;
}
const TOUCH_ABLE = (typeof navigator !== 'undefined' && navigator.maxTouchPoints > 0) || (typeof window !== 'undefined' && 'ontouchstart' in window);   // can this glass be touched at all
const touchOwn = {};   // touch identifier -> zone id it is holding

function thumbR() { return Math.max(30, Math.min(window.innerWidth, window.innerHeight) * 0.072); }   // (v1.6.1475) the thumb's unit - the first zone is the pad now, so nobody reads a radius off the table
function touchZones() {
  const W = window.innerWidth, H = window.innerHeight;
  const R = thumbR();
  return [
    { id: 'dpad',  x: 2.6 * R,       y: H - 2.6 * R, r: R * 2.3,  label: 'PAD' },   // (v1.6.1475) THE D-PAD: one pad where four discs stood - direction by the thumb's angle, sticky while held (his order: "a d pad that's way better")
    { id: 'use',   x: 5.9 * R,       y: H - 3.6 * R, r: R * 0.72, label: dumpActive() ? '\u2726' : 'USE' },   // the weapon hand announces itself
    { id: 'jump',  x: W - 1.7 * R,   y: H - 1.6 * R, r: R * 1.22, label: 'JUMP' },
    { id: 'fire',  x: W - 4.6 * R,   y: H - 1.4 * R, r: R,        label: 'FIRE' },
    { id: 'shdw',  x: W - 4.9 * R,   y: H - 3.7 * R, r: R * 0.85, label: 'SHDW' },
    { id: 'shock', x: W - 1.9 * R,   y: H - 4.3 * R, r: R * 0.85, label: 'SHOCK' },
    { id: 'rkt',   x: W - 3.6 * R,   y: H - 5.3 * R, r: R * 0.75, label: 'RKT' },
  ];
}
// THE D-PAD (v1.6.1475) — his order 2026-09-07: "the mobile needs a d pad that's way better than what it has." Four separate discs (left, right,
//   down, the gunship's up) with dead space between them were four taps; a thumb slides. Now ONE pad, 2.3 R across, at the bottom-left: the thumb
//   that lands on it owns it until it lifts, wherever it slides (even past the rim); the direction is the thumb's angle from the pad's centre -
//   left / right beyond 0.34 R sideways, down beyond 0.34 R below, up (the gunship's lift) beyond 0.34 R above, with a 0.22 R release band so a
//   held direction does not flicker at the edge, and a dead centre. Diagonals hold two directions at once (walk and crouch). The presses ride the
//   same wires as the old discs (touchZonePress 'left' / 'right' / 'down' / 'up' -> the real key events), so the double-tap dash, the tutorial's
